-- ==========================================
-- VOLTRIS OPTIMIZER - SISTEMA DE LICENCIAMENTO PRO
-- SCRIPT DE RESET E CONFIGURAÇÃO COMPLETA (V3)
-- ALINHADO COM: LicenseGenerator, LicenseManager.cs e Checkout
-- ==========================================

-- Habilitar extensões necessárias
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 1. LIMPEZA TOTAL — [INTL] DESATIVADO: o banco internacional JA TEM as tabelas
--    licenses/payments/audit_logs com dados reais e schema canonico proprio (ver
--    FASE 6 adiante: licenses PK license_key). Reaplicar os DROPs do BR aqui
--    destruiria os dados vivos do INTL.
-- DROP TABLE IF EXISTS public.licenses CASCADE;
-- DROP TABLE IF EXISTS public.payments CASCADE;
-- DROP TABLE IF EXISTS public.audit_logs CASCADE;

-- 2. TABELA DE PAGAMENTOS (PAGBANK)
-- [INTL] IF NOT EXISTS: no INTL a tabela viva permanece intocada; so num banco
-- verde ela nasce aqui.
CREATE TABLE IF NOT EXISTS public.payments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id),
    email TEXT NOT NULL,
    reference_id TEXT UNIQUE NOT NULL, -- ID do PagBank (VOLTRIS-...)
    pagbank_id TEXT, -- ID da transação no PagBank
    amount DECIMAL(10,2) NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, authorized, paid, declined
    plan_type TEXT NOT NULL, -- trial, standard, pro, enterprise
    customer_name TEXT,
    customer_tax_id TEXT, -- CPF/CNPJ
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- [INTL] Reconciliacao idempotente: colunas que o codigo do site internacional
-- usa em payments (checkout/webhook/refund/"minhas assinaturas" - provider
-- stripe). Nao altera nada que ja exista; so preenche lacunas.
ALTER TABLE public.payments
    ADD COLUMN IF NOT EXISTS provider               TEXT,
    ADD COLUMN IF NOT EXISTS stripe_id              TEXT,
    ADD COLUMN IF NOT EXISTS stripe_subscription_id TEXT,
    ADD COLUMN IF NOT EXISTS billing_period         TEXT,
    ADD COLUMN IF NOT EXISTS currency               TEXT DEFAULT 'usd';
CREATE INDEX IF NOT EXISTS idx_payments_stripe_id              ON public.payments(stripe_id);
CREATE INDEX IF NOT EXISTS idx_payments_stripe_subscription_id ON public.payments(stripe_subscription_id);

-- 3. TABELA DE LICENÇAS (COMPATÍVEL COM GERADOR C#)
CREATE TABLE IF NOT EXISTS public.licenses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_id UUID REFERENCES public.payments(id),
    user_id UUID REFERENCES auth.users(id),
    email TEXT NOT NULL,
    client_id TEXT NOT NULL, -- Parte ID da licença (ex: 230697)
    license_key TEXT UNIQUE NOT NULL, -- Chave Completa (VOLTRIS-PRO-...)
    license_type TEXT NOT NULL, -- trial, standard, pro, enterprise
    max_devices INTEGER DEFAULT 1,
    is_active BOOLEAN DEFAULT true,
    expires_at TIMESTAMPTZ NOT NULL,
    activated_at TIMESTAMPTZ,
    last_device_id TEXT, 
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 4. LOGS DE AUDITORIA
CREATE TABLE IF NOT EXISTS public.audit_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type TEXT NOT NULL,
    metadata JSONB,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- ============================================================================
-- [INTL] FASE 14 — OUTBOX TRANSACIONAL DE E-MAIL (Resend).
-- Porta do BR, adaptada ao INTL (coluna `locale` a mais). Idempotente e aditivo:
-- nada destrutivo. Fonte da verdade do envio (tentativas/retry/id Resend moram
-- aqui, pois memoria serverless morre em cold start). `idempotency_key` UNIQUE
-- impede e-mail duplicado quando a Stripe reenvia o webhook. RLS SEM policy para
-- anon/authenticated: so service_role le (guarda corpo de e-mail alheio).
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.email_outbox (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    template_type       text NOT NULL,
    idempotency_key     text NOT NULL,
    recipient_email     text NOT NULL,
    user_id             uuid REFERENCES auth.users(id) ON DELETE SET NULL,
    payment_id          uuid REFERENCES public.payments(id) ON DELETE SET NULL,
    license_key         text,
    subscription_id     text,
    locale              text,
    subject             text NOT NULL,
    html_body           text NOT NULL,
    text_body           text,
    attachment_name     text,
    attachment_content  text,
    attachment_size     integer,
    status              text NOT NULL DEFAULT 'pending',
    provider_message_id text,
    attempts            integer NOT NULL DEFAULT 0,
    available_at        timestamptz NOT NULL DEFAULT NOW(),
    last_error          text,
    last_error_kind     text,
    sent_at             timestamptz,
    delivery_status     text,
    delivered_at        timestamptz,
    opened_at           timestamptz,
    delivery_flag       text,
    delivery_flag_at    timestamptz,
    meta                jsonb,
    created_at          timestamptz NOT NULL DEFAULT NOW(),
    updated_at          timestamptz NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS uniq_email_outbox_idempotency_key
    ON public.email_outbox (idempotency_key);
CREATE INDEX IF NOT EXISTS idx_email_outbox_ready
    ON public.email_outbox (available_at) WHERE status IN ('pending', 'processing');
CREATE INDEX IF NOT EXISTS idx_email_outbox_status
    ON public.email_outbox (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_outbox_user
    ON public.email_outbox (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_outbox_provider_id
    ON public.email_outbox (provider_message_id) WHERE provider_message_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_email_outbox_delivery_flag
    ON public.email_outbox (delivery_flag_at DESC) WHERE delivery_flag IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_email_outbox_template_failed
    ON public.email_outbox (template_type, created_at DESC) WHERE status = 'failed';

CREATE OR REPLACE FUNCTION public.set_updated_at_email_outbox()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS tr_email_outbox_updated_at ON public.email_outbox;
CREATE TRIGGER tr_email_outbox_updated_at
    BEFORE UPDATE ON public.email_outbox
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_email_outbox();

ALTER TABLE public.email_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.email_outbox FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.email_outbox TO service_role;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE tablename = 'email_outbox' AND policyname = 'service role only email_outbox'
    ) THEN
        CREATE POLICY "service role only email_outbox"
            ON public.email_outbox FOR ALL TO service_role
            USING (true) WITH CHECK (true);
    END IF;
END $$;

CREATE OR REPLACE VIEW public.email_outbox_health
WITH (security_invoker = true) AS
SELECT
    status,
    count(*)::int AS total,
    min(created_at)   AS oldest_created_at,
    min(available_at) AS next_available_at,
    count(*) FILTER (WHERE last_error_kind = 'RATE_LIMIT')::int AS rate_limited,
    count(*) FILTER (WHERE last_error_kind IN ('CONFIG', 'AUTH', 'SENDER'))::int AS config_errors
FROM public.email_outbox
GROUP BY status;

-- 5. FUNÇÃO PARA GERAR ASSINATURA (ALGORITMO C#)
-- generate_voltris_signature e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'generate_voltris_signature'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.generate_voltris_signature(p_content TEXT)
RETURNS TEXT AS $$
DECLARE
    v_secret TEXT := 'VOLTRIS_SECRET_LICENSE_KEY_2025';
    v_hash TEXT;
BEGIN
    -- SHA256(Content + Secret) -> Hex Uppercase -> First 16 chars
    v_hash := upper(encode(digest(p_content || v_secret, 'sha256'), 'hex'));
    RETURN substring(v_hash from 1 for 16);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 6. FUNÇÃO PARA GERAR LICENÇA COMPLETA
-- generate_complete_license_v3 e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'generate_complete_license_v3'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.generate_complete_license_v3(
    p_payment_id UUID,
    p_user_id UUID,
    p_email TEXT,
    p_plan_type TEXT,
    p_billing_period TEXT DEFAULT 'month' -- 'month' ou 'year'
)
RETURNS JSONB AS $$
DECLARE
    v_client_id TEXT;
    v_plan_code TEXT;
    v_max_devices INTEGER;
    v_valid_until DATE;
    v_json_content TEXT;
    v_signature TEXT;
    v_final_key TEXT;
    v_license_id UUID;
    v_valid_until_str TEXT;
    v_key_date_str TEXT;
    v_interval INTERVAL;
BEGIN
    -- Determinar intervalo
    IF p_billing_period = 'year' THEN
        v_interval := INTERVAL '1 year';
    ELSE
        v_interval := INTERVAL '1 month';
    END IF;

    -- 1. Determinar Configurações do Plano
    CASE lower(p_plan_type)
        WHEN 'trial' THEN 
            v_plan_code := 'TRI';
            v_max_devices := 1;
            v_valid_until := CURRENT_DATE + INTERVAL '15 days';
        WHEN 'standard' THEN 
            v_plan_code := 'STA';
            v_max_devices := 1;
            v_valid_until := CURRENT_DATE + v_interval;
        WHEN 'pro' THEN 
            v_plan_code := 'PRO';
            v_max_devices := 3;
            v_valid_until := CURRENT_DATE + v_interval;
        WHEN 'enterprise' THEN 
            v_plan_code := 'ENT';
            v_max_devices := 9999;
            v_valid_until := CURRENT_DATE + v_interval;
        ELSE
            v_plan_code := 'STA';
            v_max_devices := 1;
            v_valid_until := CURRENT_DATE + v_interval;
    END CASE;

    -- 2. Gerar Client ID Aleatório (6 dígitos - igual ao formatado no gerador)
    v_client_id := floor(random() * (999999-100000+1) + 100000)::TEXT;

    -- 3. Preparar Formatos de Data
    v_valid_until_str := to_char(v_valid_until, 'YYYY-MM-DD'); -- Formato JSON
    v_key_date_str := to_char(v_valid_until, 'YYYYMMDD');    -- Formato Chave

    -- 4. Criar JSON de Conteúdo (EXATAMENTE como no C#)
    -- Format: {"id":"123456","validUntil":"2025-12-31","plan":"pro","maxDevices":3}
    v_json_content := format('{"id":"%s","validUntil":"%s","plan":"%s","maxDevices":%s}', 
                             v_client_id, v_valid_until_str, lower(p_plan_type), v_max_devices);

    -- 5. Gerar Assinatura
    v_signature := public.generate_voltris_signature(v_json_content);

    -- 6. Montar Chave Final
    -- Format: VOLTRIS-PRO-123456-20251231-HASH16
    v_final_key := format('VOLTRIS-%s-%s-%s-%s', v_plan_code, v_client_id, v_key_date_str, v_signature);

    -- 7. Salvar no Banco
    INSERT INTO public.licenses (
        payment_id, user_id, email, client_id, license_key, 
        license_type, max_devices, expires_at
    ) VALUES (
        p_payment_id, p_user_id, p_email, v_client_id, v_final_key, 
        p_plan_type, v_max_devices, v_valid_until
    ) RETURNING id INTO v_license_id;

    RETURN jsonb_build_object(
        'license_id', v_license_id,
        'license_key', v_final_key,
        'expires_at', v_valid_until
    );

EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.audit_logs (event_type, metadata) 
    VALUES ('LICENSE_GEN_ERROR', jsonb_build_object('error', SQLERRM, 'email', p_email));
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- 7. POLÍTICAS DE SEGURANÇA (RLS)
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.licenses ENABLE ROW LEVEL SECURITY;

-- Usuários só veem seus próprios registros
-- [INTL] DROPs adicionados: tornam estes CREATE POLICY idempotentes (sem DROP,
-- reexecutar o script daria 42710 "policy já existe" no banco INTL).
DROP POLICY IF EXISTS "Users can view own payments" ON public.payments;
DROP POLICY IF EXISTS "Users can view own licenses" ON public.licenses;
CREATE POLICY "Users can view own payments" ON public.payments FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can view own licenses" ON public.licenses FOR SELECT USING (auth.uid() = user_id OR email = (SELECT (auth.jwt() ->> 'email')));

-- Service role pode fazer tudo
DROP POLICY IF EXISTS "Service role full access on payments" ON public.payments;
CREATE POLICY "Service role full access on payments" ON public.payments FOR ALL USING (true);
DROP POLICY IF EXISTS "Service role full access on licenses" ON public.licenses;
CREATE POLICY "Service role full access on licenses" ON public.licenses FOR ALL USING (true);
