-- >>>>>>>>>>>>>>>>>> BEGIN supabase\setup_telemetry.sql >>>>>>>>>>>>>>>>>>
-- =========================================================================
-- MASTER SQL: SISTEMA DE TELEMETRIA, INSTALAÇÕES E LICENCIAMENTO ENTERPRISE
-- Projeto: Voltris Optimizer (Silicon Valley Standard)
-- =========================================================================

-- 1. EXTENSÕES E TIPOS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================================================
-- ALINHAMENTO DE ENUMS (rotulos, nao apenas existencia)
--
-- Os CREATE TYPE deste arquivo usam guarda por existencia (IF NOT EXISTS ... typname), que
-- aceita qualquer conjunto de rotulos que o banco ja tenha. Foi assim que o license_type
-- herdou o vocabulario legado do ambiente BR e morreu com 22P02 no meio do seed. Esta fase
-- aplica a mesma checagem de rotulos aos quatro tipos vivos que faltavam (os quatro do bloco
-- morto do Mercado Pago nao contam: nunca executam).
--
-- Regra por tipo:
--   nao existe .................... cria com os rotulos canonicos do arquivo;
--   existe e ja tem todos ......... nao faz nada (sobrante legado e inofensivo);
--   falta rotulo, sem dependentes .. dropa e recria exato;
--   falta rotulo, COM dependentes ... aborta com mensagem explicita. Renumerar/encurtar um
--     tipo em uso corromperia dados ja gravados, e abortar aqui fala mais claro do que
--     deixar um seed estourar 22P02 tres mil linhas adiante.
-- ============================================================================
DO $$
DECLARE
    r          RECORD;
    v_atual    text[];
    v_depen     integer;
BEGIN
    FOR r IN
        SELECT * FROM (VALUES
            ('license_status_type', ARRAY['trial', 'active', 'expired', 'revoked']),
            ('service_status',      ARRAY['active', 'inactive', 'maintenance']),
            ('notification_type',   ARRAY['ticket', 'order', 'system', 'profile', 'newsletter', 'comment']),
            ('notification_sound',  ARRAY['ping', 'chime', 'tone'])
        ) AS t(nome, rotulos)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_type ty
            JOIN pg_namespace n ON n.oid = ty.typnamespace
            WHERE ty.typname = r.nome AND n.nspname = 'public'
        ) THEN
            EXECUTE format('CREATE TYPE public.%I AS ENUM (%s)', r.nome,
                (SELECT string_agg(quote_literal(x), ', ') FROM unnest(r.rotulos) AS x));
            RAISE NOTICE '[VOLTRIS] enum % criado com rotulos (%)', r.nome, array_to_string(r.rotulos, ', ');
            CONTINUE;
        END IF;

        SELECT array_agg(e.enumlabel ORDER BY e.enumsortorder)
          INTO v_atual
          FROM pg_enum e
         WHERE e.enumtypid = ('public.' || r.nome)::regtype;

        CONTINUE WHEN r.rotulos <@ v_atual;

        SELECT count(*) INTO v_depen FROM pg_depend
         WHERE refclassid = 'pg_type'::regclass
           AND refobjid   = ('public.' || r.nome)::regtype
           AND deptype NOT IN ('a', 'i');

        IF v_depen > 0 THEN
            RAISE EXCEPTION 'enum % esta com rotulos divergentes (banco: [%], script exige: [%]) e tem % objeto(s) dependente(s). Acrescente os faltantes em execucao separada: ALTER TYPE public.% ADD VALUE ...',
                r.nome, array_to_string(v_atual, ', '), array_to_string(r.rotulos, ', '), v_depen, r.nome;
        END IF;

        EXECUTE format('DROP TYPE public.%I', r.nome);
        EXECUTE format('CREATE TYPE public.%I AS ENUM (%s)', r.nome,
            (SELECT string_agg(quote_literal(x), ', ') FROM unnest(r.rotulos) AS x));
        RAISE NOTICE '[VOLTRIS] enum % realinhado: o banco tinha (%) e passou a ter (%)',
            r.nome, array_to_string(v_atual, ', '), array_to_string(r.rotulos, ', ');
    END LOOP;
END $$;

DO $$ 
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'license_status_type') THEN
        CREATE TYPE license_status_type AS ENUM ('trial', 'active', 'expired', 'revoked');
    END IF;
END $$;

-- 2. TABELA DE INSTALAÇÕES (CORE)
-- Representa cada máquina única onde o Voltris está instalado.
CREATE TABLE IF NOT EXISTS installations (
  id UUID PRIMARY KEY, -- O GUID gerado internamente pelo App WPF
  user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL, 
  
  -- Hardware Info (Telemetria Técnica)
  app_version TEXT,
  cpu_name TEXT,
  ram_gb_total INTEGER,
  disk_main_type TEXT,
  os_name TEXT,
  os_build TEXT,
  architecture TEXT,
  
  -- Status de Licença (Sincronizado via Telemetria)
  license_key TEXT,
  license_status license_status_type DEFAULT 'trial',
  license_expires_at TIMESTAMPTZ,
  
  -- Estado de Operação
  is_optimized BOOLEAN DEFAULT FALSE,
  last_heartbeat TIMESTAMPTZ DEFAULT NOW(),
  last_optimized_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. TABELA DE EVENTOS (TELEMETRIA E AUDITORIA)
-- Registra ações específicas como "Otizimização Aplicada", "Crash", "Troca de Plano".
CREATE TABLE IF NOT EXISTS installation_events (
  id BIGSERIAL PRIMARY KEY,
  installation_id UUID REFERENCES installations(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL, -- Ex: 'APP_START', 'OPTIMIZATION_ON', 'CRASH', 'LICENSE_ACTIVATE'
  payload JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. TABELA DE HEARTBEATS (MÉTRICAS DE UPTIME)
-- Histórico bruto para geração de gráficos de uso/retenção.
CREATE TABLE IF NOT EXISTS installation_heartbeats (
  id BIGSERIAL PRIMARY KEY,
  installation_id UUID REFERENCES installations(id) ON DELETE CASCADE,
  is_optimized BOOLEAN,
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- 5. ÍNDICES DE PERFORMANCE (ESTRUTURA ENTERPRISE)
CREATE INDEX IF NOT EXISTS idx_installations_user_id ON installations(user_id);
CREATE INDEX IF NOT EXISTS idx_installations_last_heartbeat ON installations(last_heartbeat);
CREATE INDEX IF NOT EXISTS idx_installations_license_key ON installations(license_key);
CREATE INDEX IF NOT EXISTS idx_events_inst_id_type ON installation_events(installation_id, event_type);
CREATE INDEX IF NOT EXISTS idx_heartbeats_timestamp ON installation_heartbeats(timestamp);

-- 6. HABILITAR REALTIME (PARA DASHBOARD ADMIN)
DO $$ 
BEGIN
  -- Verificar se a publicação existe
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    -- Verificar se a tabela já faz parte da publicação para não dar erro ao adicionar
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables 
      WHERE pubname = 'supabase_realtime' 
      AND schemaname = 'public' 
      AND tablename = 'installations'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE installations;
    END IF;
  ELSE
    -- Se não existir a publicação padrão, cria ela com a tabela
    CREATE PUBLICATION supabase_realtime FOR TABLE installations;
  END IF;
END $$;

-- 7. SEGURANÇA (ROW LEVEL SECURITY)
ALTER TABLE installations ENABLE ROW LEVEL SECURITY;
ALTER TABLE installation_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE installation_heartbeats ENABLE ROW LEVEL SECURITY;

-- POLÍTICAS PARA 'installations'
DROP POLICY IF EXISTS "Users can view own installations" ON installations;
CREATE POLICY "Users can view own installations" ON installations 
FOR SELECT USING (auth.uid() = user_id);

