-- Trigger: Sincronizar last_active com last_heartbeat
-- sync_last_active e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'sync_last_active'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION sync_last_active()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.last_heartbeat IS DISTINCT FROM OLD.last_heartbeat THEN
        NEW.last_active = NEW.last_heartbeat;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- [INTL] DROP IF EXISTS: re-execução / preexistência no INTL (42710)
