-- >>>>>>>>>>>>>>>>>> BEGIN supabase\fix_telemetry_final.sql >>>>>>>>>>>>>>>>>>
-- =========================================================================
-- FIX TELEMETRY SYSTEM - Final Version (handles existing tables)
-- =========================================================================

-- 1. DROP EXISTING TABLES IF THEY HAVE WRONG SCHEMA
-- [INTL] DROPs destrutivos DESATIVADOS: re-executar este arquivo não deve apagar
-- telemetria existente. As tabelas do INTL já nascem no shape final do BR (criações
-- abaixo viraram IF NOT EXISTS).
-- DROP TABLE IF EXISTS telemetry_events CASCADE;
-- DROP TABLE IF EXISTS sessions CASCADE;
-- DROP TABLE IF EXISTS device_profiles CASCADE;
-- DROP TABLE IF EXISTS devices CASCADE;

-- 2. CREATE COMPANIES TABLE
CREATE TABLE IF NOT EXISTS companies (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  plan_type TEXT DEFAULT 'personal',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. CREATE DEVICES TABLE (fresh with correct schema)
CREATE TABLE IF NOT EXISTS devices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  machine_id UUID UNIQUE NOT NULL,
  hostname TEXT NOT NULL DEFAULT 'Unknown',
  os_version TEXT,
  architecture TEXT DEFAULT 'x64',
  company_id UUID REFERENCES companies(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. CREATE DEVICE_PROFILES TABLE
CREATE TABLE IF NOT EXISTS device_profiles (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  device_id UUID REFERENCES devices(id) ON DELETE CASCADE,
  cpu_model TEXT,
  gpu_model TEXT,
  ram_total_gb INTEGER,
  disk_type TEXT,
  os_version TEXT,
  windows_build TEXT,
  windows_edition TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(device_id)
);

-- 5. CREATE SESSIONS TABLE
CREATE TABLE IF NOT EXISTS sessions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  device_id UUID REFERENCES devices(id) ON DELETE CASCADE,
  status TEXT DEFAULT 'active',
  started_at TIMESTAMPTZ DEFAULT NOW(),
  last_heartbeat_at TIMESTAMPTZ DEFAULT NOW(),
  ended_at TIMESTAMPTZ,
  app_version TEXT,
  health_score INTEGER,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. CREATE TELEMETRY_EVENTS TABLE
CREATE TABLE IF NOT EXISTS telemetry_events (
  id BIGSERIAL PRIMARY KEY,
  session_id UUID REFERENCES sessions(id) ON DELETE CASCADE,
  device_id UUID REFERENCES devices(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  feature_name TEXT,
  action_name TEXT,
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- [INTL][patch] Colunas que as rotas do app (intelligence/deploy/privacy/cost-analysis)
-- leem/escrevem em telemetry_events mas faltavam em QUALQUER criação do arquivo.
-- No BR vivo as tabelas co-evoluíram; aqui a criação IF NOT EXISTS ocultava isso.
-- Só ADD IF NOT EXISTS: não quebra re-execução nem dados existentes.
ALTER TABLE public.telemetry_events ADD COLUMN IF NOT EXISTS duration_ms INTEGER;
ALTER TABLE public.telemetry_events ADD COLUMN IF NOT EXISTS success BOOLEAN;
ALTER TABLE public.telemetry_events ADD COLUMN IF NOT EXISTS error_code TEXT;
ALTER TABLE public.telemetry_events ADD COLUMN IF NOT EXISTS timestamp TIMESTAMPTZ DEFAULT now();
UPDATE public.telemetry_events SET timestamp = created_at WHERE timestamp IS NULL;

-- [INTL][patch] Idem para performance_metrics (criada mais à frente em
-- services\telemetry-schema.sql com shape UUID; reconciliação cobre as duas ordens
-- de criação possíveis).
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS cpu_before NUMERIC;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS cpu_after NUMERIC;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS ram_before_mb INTEGER;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS ram_after_mb INTEGER;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS disk_before_gb NUMERIC;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS disk_after_gb NUMERIC;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS boot_time_before INTEGER;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS boot_time_after INTEGER;
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS timestamp TIMESTAMPTZ DEFAULT now();
ALTER TABLE IF EXISTS public.performance_metrics ADD COLUMN IF NOT EXISTS device_id UUID;

-- 7. ADD MISSING COLUMNS TO INSTALLATIONS
ALTER TABLE installations ADD COLUMN IF NOT EXISTS gpu_name TEXT;
ALTER TABLE installations ADD COLUMN IF NOT EXISTS disk_type TEXT;
ALTER TABLE installations ADD COLUMN IF NOT EXISTS windows_edition TEXT;
ALTER TABLE installations ADD COLUMN IF NOT EXISTS hostname TEXT;
ALTER TABLE installations ADD COLUMN IF NOT EXISTS architecture TEXT DEFAULT 'x64';

-- 8. MIGRATE DATA FROM INSTALLATIONS
-- Insert devices
INSERT INTO devices (machine_id, hostname, os_version, architecture, created_at)
SELECT 
  i.id,
  COALESCE(NULLIF(TRIM(i.hostname), ''), 'Unknown'),
  COALESCE(i.os_name, 'Windows'),
  COALESCE(i.architecture, 'x64'),
  i.created_at
FROM installations i ON CONFLICT DO NOTHING ;

-- Insert device profiles
INSERT INTO device_profiles (device_id, cpu_model, gpu_model, ram_total_gb, disk_type, os_version, windows_build, windows_edition)
SELECT 
  d.id,
  i.cpu_name,
  COALESCE(i.gpu_name, 'Unknown GPU'),
  i.ram_gb_total,
  COALESCE(i.disk_type, 'HDD'),
  i.os_name,
  i.os_build,
  i.windows_edition
FROM installations i
JOIN devices d ON d.machine_id = i.id ON CONFLICT DO NOTHING ;

-- Create sessions for recent heartbeats
INSERT INTO sessions (device_id, status, started_at, last_heartbeat_at, app_version, health_score)
SELECT 
  d.id,
  CASE 
    WHEN i.last_heartbeat > NOW() - INTERVAL '5 minutes' THEN 'active'
    WHEN i.last_heartbeat > NOW() - INTERVAL '30 minutes' THEN 'idle'
    ELSE 'closed'
  END,
  i.created_at,
  i.last_heartbeat,
  i.app_version,
  100
FROM installations i
JOIN devices d ON d.machine_id = i.id
WHERE i.last_heartbeat > NOW() - INTERVAL '30 minutes' ON CONFLICT DO NOTHING ;

-- 9. CREATE INDEXES
CREATE INDEX IF NOT EXISTS idx_devices_machine_id ON devices(machine_id);
CREATE INDEX IF NOT EXISTS idx_devices_hostname ON devices(hostname);
CREATE INDEX IF NOT EXISTS idx_device_profiles_device_id ON device_profiles(device_id);
CREATE INDEX IF NOT EXISTS idx_sessions_device_id ON sessions(device_id);
CREATE INDEX IF NOT EXISTS idx_sessions_status ON sessions(status);
CREATE INDEX IF NOT EXISTS idx_sessions_last_heartbeat ON sessions(last_heartbeat_at);
CREATE INDEX IF NOT EXISTS idx_telemetry_events_session_id ON telemetry_events(session_id);
CREATE INDEX IF NOT EXISTS idx_telemetry_events_event_type ON telemetry_events(event_type);
CREATE INDEX IF NOT EXISTS idx_telemetry_events_created_at ON telemetry_events(created_at);

-- 10. ENABLE ROW LEVEL SECURITY
ALTER TABLE devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE device_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE telemetry_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;

-- 11. CREATE POLICIES
-- [INTL] DROPs adicionados: os CREATE POLICY nus quebravam re-execução (42710)
DROP POLICY IF EXISTS "Service role can manage devices" ON devices;
CREATE POLICY "Service role can manage devices" ON devices FOR ALL USING (true);
DROP POLICY IF EXISTS "Admins can view all devices" ON devices;
CREATE POLICY "Admins can view all devices" ON devices FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

DROP POLICY IF EXISTS "Service role can manage device_profiles" ON device_profiles;
CREATE POLICY "Service role can manage device_profiles" ON device_profiles FOR ALL USING (true);
DROP POLICY IF EXISTS "Admins can view all device_profiles" ON device_profiles;
CREATE POLICY "Admins can view all device_profiles" ON device_profiles FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

DROP POLICY IF EXISTS "Service role can manage sessions" ON sessions;
CREATE POLICY "Service role can manage sessions" ON sessions FOR ALL USING (true);
DROP POLICY IF EXISTS "Admins can view all sessions" ON sessions;
CREATE POLICY "Admins can view all sessions" ON sessions FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

DROP POLICY IF EXISTS "Service role can manage telemetry_events" ON telemetry_events;
CREATE POLICY "Service role can manage telemetry_events" ON telemetry_events FOR ALL USING (true);
DROP POLICY IF EXISTS "Admins can view all telemetry_events" ON telemetry_events;
CREATE POLICY "Admins can view all telemetry_events" ON telemetry_events FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

DROP POLICY IF EXISTS "Service role can manage companies" ON companies;
CREATE POLICY "Service role can manage companies" ON companies FOR ALL USING (true);
DROP POLICY IF EXISTS "Admins can view all companies" ON companies;
CREATE POLICY "Admins can view all companies" ON companies FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

-- 12. CREATE TRIGGERS
-- update_device_updated_at e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'update_device_updated_at'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION update_device_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

-- [INTL] OR REPLACE adicionado: CREATE TRIGGER nu quebrava re-execução (42710)
DROP TRIGGER IF EXISTS tr_devices_updated_at ON devices;
CREATE TRIGGER tr_devices_updated_at
BEFORE UPDATE ON devices FOR EACH ROW
EXECUTE PROCEDURE update_device_updated_at();

DROP TRIGGER IF EXISTS tr_device_profiles_updated_at ON device_profiles;
CREATE TRIGGER tr_device_profiles_updated_at
BEFORE UPDATE ON device_profiles FOR EACH ROW
EXECUTE PROCEDURE update_device_updated_at();

-- 13. CREATE FUNCTION TO CLEAN OLD SESSIONS
-- cleanup_old_sessions e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'cleanup_old_sessions'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION cleanup_old_sessions()
RETURNS void AS $$
BEGIN
  UPDATE sessions 
  SET status = 'closed', ended_at = last_heartbeat_at
  WHERE status IN ('active', 'idle') 
    AND last_heartbeat_at < NOW() - INTERVAL '30 minutes';
END;
$$ LANGUAGE plpgsql;

-- 14. ENABLE REALTIME
DO $$ 
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE sessions;
    ALTER PUBLICATION supabase_realtime ADD TABLE devices;
    ALTER PUBLICATION supabase_realtime ADD TABLE device_profiles;
  END IF;
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

-- 15. COMMENTS
COMMENT ON TABLE devices IS 'Stores unique device information for each machine running Voltris';
COMMENT ON TABLE device_profiles IS 'Hardware profiles for each device';
COMMENT ON TABLE sessions IS 'Active and historical app sessions';
COMMENT ON TABLE telemetry_events IS 'Detailed event tracking for analytics';
COMMENT ON TABLE companies IS 'Company/organization information for enterprise users';
-- <<<<<<<<<<<<<<<<<< END supabase\fix_telemetry_final.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\FIX_STRIPE_LICENSE.sql >>>>>>>>>>>>>>>>>>
-- ==========================================
-- VOLTRIS - STRIPE LICENSE GENERATION FIX
-- Resolve o erro do webhook passando a variável p_billing_period
-- ==========================================

-- 1. Excluir todas as variantes antigas da função para evitar conflito de overloading
DROP FUNCTION IF EXISTS public.generate_complete_license_v3(UUID, UUID, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.generate_complete_license_v3(UUID, UUID, TEXT, TEXT, TEXT);

-- 2. Recriar a função principal aceitando todos os 5 parâmetros exigidos pelo Webhook
-- generate_complete_license_v3 e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'generate_complete_license_v3'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.generate_complete_license_v3(
    p_payment_id UUID,
    p_user_id UUID,
    p_email TEXT,
    p_plan_type TEXT,
    p_billing_period TEXT DEFAULT 'month' -- Exigido pelo Webhook do Stripe
)
RETURNS JSONB AS $$
DECLARE
    v_client_id TEXT;
    v_plan_code TEXT;
    v_max_devices INTEGER;
    v_valid_until DATE;
    v_json_content TEXT;
    v_signature TEXT;
    v_final_key TEXT;
    v_license_id UUID;
    v_valid_until_str TEXT;
    v_key_date_str TEXT;
    v_interval INTERVAL;
BEGIN
    -- 1. Determinar intervalo pelo período do Stripe
    IF p_billing_period = 'year' THEN
        v_interval := INTERVAL '1 year';
    ELSE
        v_interval := INTERVAL '1 month';
    END IF;

    -- 2. Determinar Configurações do Plano
    CASE lower(p_plan_type)
        WHEN 'trial' THEN 
            v_plan_code := 'TRI'; v_max_devices := 1;
            v_valid_until := CURRENT_DATE + INTERVAL '15 days';
        WHEN 'standard' THEN 
            v_plan_code := 'STA'; v_max_devices := 1;
            v_valid_until := CURRENT_DATE + v_interval;
        WHEN 'pro' THEN 
            v_plan_code := 'PRO'; v_max_devices := 3;
            v_valid_until := CURRENT_DATE + v_interval;
        WHEN 'enterprise' THEN 
            v_plan_code := 'ENT'; v_max_devices := 9999;
            v_valid_until := CURRENT_DATE + v_interval;
        ELSE
            v_plan_code := 'STA'; v_max_devices := 1;
            v_valid_until := CURRENT_DATE + v_interval;
    END CASE;

    -- 3. Gerar Client ID Aleatório (6 dígitos - igual ao formatado no gerador)
    v_client_id := floor(random() * (999999-100000+1) + 100000)::TEXT;

    -- 4. Preparar Formatos de Data
    v_valid_until_str := to_char(v_valid_until, 'YYYY-MM-DD'); 
    v_key_date_str := to_char(v_valid_until, 'YYYYMMDD');

    -- 5. Criar JSON de Conteúdo
    v_json_content := format('{"id":"%s","validUntil":"%s","plan":"%s","maxDevices":%s}', 
                             v_client_id, v_valid_until_str, lower(p_plan_type), v_max_devices);

    -- 6. Gerar Assinatura via VOLTRIS
    v_signature := public.generate_voltris_signature(v_json_content);

    -- 7. Montar Chave Final
    v_final_key := format('VOLTRIS-%s-%s-%s-%s', v_plan_code, v_client_id, v_key_date_str, v_signature);

    -- 8. Salvar no Banco
    INSERT INTO public.licenses (
        payment_id, user_id, email, client_id, license_key, 
        license_type, max_devices, expires_at
    ) VALUES (
        p_payment_id, p_user_id, p_email, v_client_id, v_final_key, 
        p_plan_type, v_max_devices, v_valid_until
    ) RETURNING id INTO v_license_id;

    RETURN jsonb_build_object(
        'license_id', v_license_id,
        'license_key', v_final_key,
        'expires_at', v_valid_until
    );

EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.audit_logs (event_type, metadata) 
    VALUES ('LICENSE_GEN_ERROR', jsonb_build_object('error', SQLERRM, 'email', p_email));
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
-- <<<<<<<<<<<<<<<<<< END supabase\FIX_STRIPE_LICENSE.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\FIX_LICENSE_COUNTER_SYNC.sql >>>>>>>>>>>>>>>>>>
-- ============================================================
-- VOLTRIS - LICENSE COUNTER SYNC FIX
-- Garante que o contador 'devices_in_use' da tabela 'licenses' 
-- esteja sempre sincronizado com a tabela 'license_devices'.
-- ============================================================

-- [INTL][skip] FIX_LICENSE_COUNTER_SYNC: linhagem SUPERADA pela FASE 6 (ver
-- comentário na seção de repair: tr_sync_license_device_count referencia
-- licenses.id / license_devices.license_id / licenses.devices_in_use — colunas
-- que NÃO existem no schema canônico). A contagem de dispositivos no INTL é a
-- COUNT real de license_devices por license_key (api /license/activate), não um
-- contador denormalizado. A versão canônica desta trigger está na FASE 6.
/*
-- 1. Função para atualizar o contador de dispositivos em uso
CREATE OR REPLACE FUNCTION public.sync_license_device_count()
RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        UPDATE public.licenses 
        SET devices_in_use = (SELECT count(*) FROM public.license_devices WHERE license_id = NEW.license_id),
            activated_at = COALESCE(activated_at, NOW())
        WHERE id = NEW.license_id;
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        UPDATE public.licenses 
        SET devices_in_use = (SELECT count(*) FROM public.license_devices WHERE license_id = OLD.license_id)
        WHERE id = OLD.license_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 2. Criar a trigger na tabela license_devices
DROP TRIGGER IF EXISTS tr_sync_license_device_count ON public.license_devices;
CREATE TRIGGER tr_sync_license_device_count
AFTER INSERT OR DELETE ON public.license_devices
FOR EACH ROW
EXECUTE FUNCTION public.sync_license_device_count();

-- 3. Sincronizar dados existentes (opcional, mas recomendado para corrigir o 0/1 atual)
UPDATE public.licenses l
SET devices_in_use = (
    SELECT count(*) 
    FROM public.license_devices ld 
    WHERE ld.license_id = l.id
);

-- 4. Adicionar nota ao log de auditoria
INSERT INTO public.audit_logs (event_type, metadata)
VALUES ('SYSTEM_FIX', '{"description": "Sincronização de contagem de dispositivos de licença implementada via trigger"}') */
-- <<<<<<<<<<<<<<<<<< END supabase\FIX_LICENSE_COUNTER_SYNC.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\FIX_RLS_LEAK.sql >>>>>>>>>>>>>>>>>>
-- ============================================================
-- VOLTRIS — SECURITY HARDENING: FIX RLS LEAKS
-- Este script corrige políticas que permitem acesso anônimo excessivo.
-- ============================================================

-- 1. TABELA: payments
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "service_all_payments" ON public.payments;
CREATE POLICY "service_all_payments" ON public.payments
    TO service_role
    USING (true)
    WITH CHECK (true);

-- 2. TABELA: licenses
ALTER TABLE public.licenses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "service_all_licenses" ON public.licenses;
CREATE POLICY "service_all_licenses" ON public.licenses
    TO service_role
    USING (true)
    WITH CHECK (true);

-- 3. TABELA: subscriptions
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service role full access subscriptions" ON public.subscriptions;
CREATE POLICY "Service role full access subscriptions" ON public.subscriptions
    TO service_role
    USING (true)
    WITH CHECK (true);

-- 4. TABELA: audit_logs
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "service_all_audit_logs" ON public.audit_logs;
CREATE POLICY "service_all_audit_logs" ON public.audit_logs
    TO service_role
    USING (true)
    WITH CHECK (true);

-- 5. TABELA: profiles (Garantindo que admins podem ver tudo, mas anônimos não)
DROP POLICY IF EXISTS "Admins can view all profiles" ON public.profiles;
CREATE POLICY "Admins can view all profiles" ON public.profiles
    FOR SELECT
    TO authenticated
    USING (
      (auth.jwt() ->> 'email') IN (SELECT email FROM public.profiles WHERE is_admin = true)
      OR auth.uid() = id
    );

-- Nota: Para o 'service_role' (usado nos Server Actions / API), o RLS é ignorado por padrão.
-- Estas políticas garantem que o 'anon' role não consiga ler dados via 'true' sem verificação.
-- <<<<<<<<<<<<<<<<<< END supabase\FIX_RLS_LEAK.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\FIX_RLS_RECURSION.sql >>>>>>>>>>>>>>>>>>
-- ============================================================
-- VOLTRIS — SECURITY BUGFIX: FIX INFINITE RLS RECURSION
-- Resolve o erro "infinite recursion detected in policy for relation profiles"
-- ============================================================

-- 1. Excluir a política defeituosa que causa o loop infinito
DROP POLICY IF EXISTS "Admins can view all profiles" ON public.profiles;

-- 2. Garantir que todo usuário logado consiga pelo menos ver o seu PRÓPRIO perfil
-- (Criamos caso não exista ou sobreescrevemos a existente de forma segura)
DROP POLICY IF EXISTS "Users can view own profile" ON public.profiles;
CREATE POLICY "Users can view own profile" ON public.profiles
    FOR SELECT 
    TO authenticated 
    USING ( auth.uid() = id );

-- 3. Criar uma função ignorando RLS (SECURITY DEFINER) para verificar a flag de admin.
-- Isso é fundamental porque evita que a checagem de Admin dispare o RLS da tabela denovo.
CREATE OR REPLACE FUNCTION public.check_is_admin()
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER SET search_path = public
AS $$
  SELECT is_admin FROM public.profiles WHERE id = auth.uid() LIMIT 1;
$$;

-- 4. Criar a política de administradores utilizando a nova função segura
DROP POLICY IF EXISTS "Admins view all profiles securely" ON public.profiles; -- [INTL] idempotencia 42710
CREATE POLICY "Admins view all profiles securely" ON public.profiles
    FOR SELECT 
    TO authenticated 
    USING ( public.check_is_admin() );
-- <<<<<<<<<<<<<<<<<< END supabase\FIX_RLS_RECURSION.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\update_hostnames.sql >>>>>>>>>>>>>>>>>>
-- =========================================================================
-- UPDATE HOSTNAMES - Fix "Unknown" devices with actual computer names
-- =========================================================================

-- Update devices table with actual hostnames from Windows environment
-- This will set the hostname to the machine name from the installation

-- Option 1: If you know the hostname, update manually
-- UPDATE devices 
-- SET hostname = 'DESKTOP-65TSNJ8' 
-- WHERE machine_id = '612f0f8d-8780-42f9-8daf-3bdffe299bc6';

-- Option 2: Try to extract from CPU name or other fields (temporary fix)
-- This assumes the hostname might be stored somewhere in installations
UPDATE devices d
SET hostname = COALESCE(
  -- Try to get from installations if hostname column exists
  (SELECT NULLIF(TRIM(i.hostname), '') FROM installations i WHERE i.id = d.machine_id),
  -- Otherwise keep as Unknown for now
  'Unknown'
)
WHERE d.hostname = 'Unknown';

-- Show current devices to verify
SELECT 
  d.hostname,
  d.machine_id,
  d.os_version,
  dp.cpu_model,
  dp.gpu_model,
  dp.ram_total_gb
FROM devices d
LEFT JOIN device_profiles dp ON dp.device_id = d.id;
-- <<<<<<<<<<<<<<<<<< END supabase\update_hostnames.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN services\enterprise-schema.sql >>>>>>>>>>>>>>>>>>
-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. COMPANIES Table
CREATE TABLE IF NOT EXISTS public.companies (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name TEXT NOT NULL,
    cnpj TEXT,
    plan_type TEXT DEFAULT 'standard', -- standard, pro, enterprise
    max_devices INTEGER DEFAULT 5,
    license_key TEXT UNIQUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    subscription_status TEXT DEFAULT 'active', -- active, overdue, cancelled
    subscription_end TIMESTAMP WITH TIME ZONE
);

-- 2. COMPANY_USERS Table (Linking Auth Users to Companies)
CREATE TABLE IF NOT EXISTS public.company_users (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE,
    user_id UUID NOT NULL, -- References auth.users.id (Supabase Auth)
    role TEXT DEFAULT 'viewer', -- owner, admin, viewer
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    UNIQUE(company_id, user_id)
);

-- 3. DEVICES Table (PCs)
CREATE TABLE IF NOT EXISTS public.devices (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE,
    machine_id TEXT NOT NULL, -- Computed Hash from Desktop App
    hostname TEXT,
    os_version TEXT,
    cpu_model TEXT,
    ram_total_gb DECIMAL(10,2),
    disk_serial TEXT,
    mac_address TEXT,
    
    status TEXT DEFAULT 'offline', -- online, offline
    last_heartbeat TIMESTAMP WITH TIME ZONE,
    
    is_license_revoked BOOLEAN DEFAULT FALSE,
    app_version TEXT,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    UNIQUE(company_id, machine_id)
);

-- 4. TELEMETRY_LOGS Table (TimeSeries Data)
CREATE TABLE IF NOT EXISTS public.telemetry_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    device_id UUID REFERENCES public.devices(id) ON DELETE CASCADE,
    company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE,
    
    cpu_usage DECIMAL(5,2),
    ram_usage_percent DECIMAL(5,2),
    disk_usage_percent DECIMAL(5,2),
    boot_time_seconds DECIMAL(10,2),
    
    timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create index for faster querying of telemetry
CREATE INDEX IF NOT EXISTS idx_telemetry_device_time ON public.telemetry_logs (device_id, timestamp DESC);

-- 5. ALERTS Table
CREATE TABLE IF NOT EXISTS public.device_alerts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    device_id UUID REFERENCES public.devices(id) ON DELETE CASCADE,
    company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE,
    
    type TEXT NOT NULL, -- RAM_HIGH, DISK_FULL, etc
    level TEXT NOT NULL, -- WARNING, CRITICAL
    message TEXT,
    is_resolved BOOLEAN DEFAULT FALSE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    resolved_at TIMESTAMP WITH TIME ZONE
);

-- 6. REMOTE COMMANDS Table
CREATE TABLE IF NOT EXISTS public.remote_commands (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    device_id UUID REFERENCES public.devices(id) ON DELETE CASCADE,
    company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE,
    create_user_id UUID, -- Who requested the command
    
    command_type TEXT NOT NULL, -- OPTIMIZE_RAM, CLEAN_SYSTEM, UPDATE_POLICY, REMOTE_LOCK
    payload JSONB DEFAULT '{}',
    status TEXT DEFAULT 'pending', -- pending, sent, completed, failed
    
    result_data JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    executed_at TIMESTAMP WITH TIME ZONE
);

-- Row Level Security (RLS) Policies (Examples)
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.devices ENABLE ROW LEVEL SECURITY;

-- Note: In a real deployment, you must create policies that allow access based on company_users table.
-- Example:
-- CREATE POLICY "Users can view devices of their company" ON public.devices
-- FOR SELECT USING (
--   EXISTS (
--     SELECT 1 FROM public.company_users cu
--     WHERE cu.user_id = auth.uid() AND cu.company_id = public.devices.company_id
--   )
-- );
-- <<<<<<<<<<<<<<<<<< END services\enterprise-schema.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN services\telemetry-schema.sql >>>>>>>>>>>>>>>>>>
-- =============================================
-- VOLTRIS OPTIMIZER - ENTERPRISE TELEMETRY SCHEMA
-- =============================================

-- 1. DEVICE INTELLIGENCE (Perfil detalhado do Hardware)
CREATE TABLE IF NOT EXISTS public.device_profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    device_id UUID NOT NULL REFERENCES public.devices(id) ON DELETE CASCADE,
    cpu_model TEXT,
    gpu_model TEXT,
    ram_total_gb NUMERIC(5,2),
    disk_type TEXT, -- SSD, NVMe, HDD
    os_version TEXT, -- Windows 11 Pro
    windows_build TEXT, -- 22631.3007
    is_64bit BOOLEAN,
    is_admin BOOLEAN,
    screen_resolution TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(device_id) 
);

-- 2. ACTIVITY SESSIONS (Sessões detalhadas)
-- (Sua tabela 'sessions' atual foca em estado, vamos criar uma de histórico se necessário, 
-- ou alterar a session atual para suportar metrics de encerramento)
ALTER TABLE public.sessions 
ADD COLUMN IF NOT EXISTS close_reason TEXT DEFAULT 'unknown', -- 'user_exit', 'crash', 'shutdown', 'update'
ADD COLUMN IF NOT EXISTS duration_seconds INTEGER DEFAULT 0;

-- 3. TELEMETRY EVENTS (Log Comportamental - A "Jornada do Usuário")
CREATE TABLE IF NOT EXISTS public.telemetry_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID REFERENCES public.sessions(id) ON DELETE SET NULL,
    device_id UUID REFERENCES public.devices(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL, -- 'APP_START', 'FEATURE_USE', 'ERROR', 'PERFORMANCE'
    feature_name TEXT, -- 'SmartResume', 'GamerMode', 'Cleaner'
    action_name TEXT, -- 'Click', 'Execute', 'View'
    duration_ms INTEGER, -- Tempo que a ação levou (ex: limpeza demorou 500ms)
    success BOOLEAN,
    error_code TEXT,
    metadata JSONB, -- Dados extras flexíveis
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 4. PERFORMANCE METRICS (Antes e Depois)
CREATE TABLE IF NOT EXISTS public.performance_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- [INTL][patch] 42804: esta criação (linhagem services) é pulada em banco novo
    -- — a vencedora é a do fix_telemetry_final (id BIGSERIAL). Um FK UUID→bigint
    -- quebraria; no BR vivo o DROP...CASCADE histórico também derrubou esta FK.
    -- event_id fica UUID SEM FK, replicando o estado final do BR.
    event_id UUID,
    cpu_usage_before NUMERIC(5,2),
    cpu_usage_after NUMERIC(5,2),
    ram_usage_before_mb INTEGER,
    ram_usage_after_mb INTEGER,
    disk_free_before_gb NUMERIC(10,2),
    disk_free_after_gb NUMERIC(10,2),
    processes_count_before INTEGER,
    processes_count_after INTEGER,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 5. POLICIES (Segurança RLS)
ALTER TABLE public.device_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.telemetry_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.performance_metrics ENABLE ROW LEVEL SECURITY;

-- Permitir INSERT público (o app manda dados), mas SELECT apenas para admin (service_role ignora RLS, admin dashboard usa service role ou admin user)
DROP POLICY IF EXISTS "Apps can insert profiles" ON public.device_profiles;
CREATE POLICY "Apps can insert profiles" ON public.device_profiles FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Apps can update profiles" ON public.device_profiles;
CREATE POLICY "Apps can update profiles" ON public.device_profiles FOR UPDATE USING (true);

DROP POLICY IF EXISTS "Apps can insert events" ON public.telemetry_events;
CREATE POLICY "Apps can insert events" ON public.telemetry_events FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Apps can insert metrics" ON public.performance_metrics;
CREATE POLICY "Apps can insert metrics" ON public.performance_metrics FOR INSERT WITH CHECK (true);

-- Indexação para Alta Performance no Dashboard
CREATE INDEX IF NOT EXISTS idx_telemetry_session ON public.telemetry_events(session_id);
-- [INTL][patch] reativado: device_id foi adicionado à criação vencedora acima
-- (as rotas do app filtram por device_id).
CREATE INDEX IF NOT EXISTS idx_telemetry_device ON public.telemetry_events(device_id);
CREATE INDEX IF NOT EXISTS idx_telemetry_type ON public.telemetry_events(event_type);
CREATE INDEX IF NOT EXISTS idx_telemetry_created ON public.telemetry_events(created_at DESC);
-- <<<<<<<<<<<<<<<<<< END services\telemetry-schema.sql <<<<<<<<<<<<<<<<<<

