-- Função para atualizar automaticamente o updated_at
-- update_orders_updated_at e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'update_orders_updated_at'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION update_orders_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger para atualizar updated_at automaticamente
DROP TRIGGER IF EXISTS update_orders_updated_at_trigger ON orders;
CREATE TRIGGER update_orders_updated_at_trigger
    BEFORE UPDATE ON orders
    FOR EACH ROW
    EXECUTE FUNCTION update_orders_updated_at();
