        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION get_user_orders_with_details(user_uuid UUID)
RETURNS TABLE (
    id UUID,
    user_id UUID,
    service_id TEXT,
    service_name TEXT,
    service_description TEXT,
    plan_type TEXT,
    final_price NUMERIC,
    payment_method TEXT,
    status TEXT,
    payment_status TEXT,
    notes TEXT,
    created_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        o.id,
        o.user_id,
        o.service_id,
        o.service_name,
        o.service_description,
        o.plan_type,
        o.final_price,
        o.payment_method,
        o.status,
        o.payment_status,
        o.notes,
        o.created_at,
        o.updated_at
    FROM orders o
    WHERE o.user_id = user_uuid
    ORDER BY o.created_at DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

