-- >>>>>>>>>>>>>>>>>> BEGIN supabase\migrations\20240711000000_fix_signup_trigger.sql >>>>>>>>>>>>>>>>>>
-- Corrigir trigger de cadastro para garantir que todos os campos sejam salvos
-- Remover trigger antiga
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;

-- Remover função antiga
DROP FUNCTION IF EXISTS public.handle_new_user();

-- Criar função corrigida para criar perfil ao criar usuário
-- handle_new_user e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'handle_new_user'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    -- login pode colidir (a coluna e UNIQUE) e o cadastro manda country que antes
    -- era descartado; ver comentarios junto do INSERT.
    v_login text := COALESCE(NEW.raw_user_meta_data->>'login', split_part(NEW.email, '@', 1));
BEGIN
    -- Debug: log dos dados recebidos
    RAISE NOTICE 'Criando perfil para usuário: %', NEW.id;
    RAISE NOTICE 'Dados recebidos: login=%, full_name=%, phone=%, address=%, city=%, neighborhood=%, state=%, cep=%', 
        NEW.raw_user_meta_data->>'login',
        NEW.raw_user_meta_data->>'full_name',
        NEW.raw_user_meta_data->>'phone',
        NEW.raw_user_meta_data->>'address',
        NEW.raw_user_meta_data->>'city',
        NEW.raw_user_meta_data->>'neighborhood',
        NEW.raw_user_meta_data->>'state',
        NEW.raw_user_meta_data->>'cep';
    
    -- 1) profiles.login e UNIQUE (L43). Dois cadastros cuja parte local do e-mail
    --    era igual (a@gmail.com e a@outlook.com) colidiam, o INSERT devolvia 23505
    --    e o GoTrue respondia 500 "Database error saving new user": a conta nao
    --    nascia e ninguem sabia por que. Aqui o login repetido ganha sufixo.
    -- 2) country vinha no metadata do cadastro e era descartado: o perfil nascia
    --    sem pais e o formulario de completar cadastro caia no padrao Brazil num
    --    site internacional.
    -- 3) ON CONFLICT (id) DO NOTHING: se o perfil ja existe (re-execucao, ou corrida
    --    com o insert administrativo de /auth/callback), o trigger NAO pode abortar
    --    o INSERT em auth.users.
    IF v_login IS NULL OR v_login = '' THEN
        v_login := 'usuario';
    END IF;

    IF EXISTS (SELECT 1 FROM public.profiles pr WHERE pr.login = v_login) THEN
        v_login := v_login || '_' || left(NEW.id::text, 8);
    END IF;

    INSERT INTO public.profiles (
        id,
        login,
        email,
        full_name,
        phone,
        address,
        city,
        neighborhood,
        state,
        cep,
        country,
        preferred_locale,
        is_admin,
        role
    )
    VALUES (
        NEW.id,
        v_login,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
        COALESCE(NEW.raw_user_meta_data->>'phone', ''),
        COALESCE(NEW.raw_user_meta_data->>'address', ''),
        COALESCE(NEW.raw_user_meta_data->>'city', ''),
        COALESCE(NEW.raw_user_meta_data->>'neighborhood', ''),
        COALESCE(NEW.raw_user_meta_data->>'state', ''),
        COALESCE(NEW.raw_user_meta_data->>'cep', ''),
        COALESCE(NEW.raw_user_meta_data->>'country', ''),
        COALESCE(NEW.raw_user_meta_data->>'preferred_locale', 'en'),
        false,
        'user'
    )
    ON CONFLICT (id) DO NOTHING;
    
    RAISE NOTICE 'Perfil criado com sucesso para usuário: %', NEW.id;
    RETURN NEW;
END;
$$;

-- Criar a trigger para criar perfil ao criar usuário
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW
    EXECUTE FUNCTION public.handle_new_user();

-- Garantir que as policies estejam corretas
DROP POLICY IF EXISTS "Usuários podem ver seus próprios perfis" ON public.profiles;
DROP POLICY IF EXISTS "Usuários podem atualizar seus próprios perfis" ON public.profiles;
DROP POLICY IF EXISTS "Permitir insert do próprio perfil" ON public.profiles;
DROP POLICY IF EXISTS "Admins podem ver todos os perfis" ON public.profiles;

-- Usuário pode ver o próprio perfil
CREATE POLICY "Usuários podem ver seus próprios perfis"
    ON public.profiles
    FOR SELECT
    USING (auth.uid() = id);

-- Admin pode ver todos os perfis (além do próprio).
-- A checagem de admin NÃO pode ler public.profiles daqui: essa subconsulta aciona as
-- próprias policies de profiles, que acionam esta de novo, e o PostgreSQL mata a
-- consulta com "infinite recursion detected in policy for relation profiles" (o 500
-- que o dashboard recebe em profiles?select=*). O arquivo já define
-- public.check_is_admin() como SECURITY DEFINER (lê profiles furando o RLS), então é
-- ela que vale aqui.
CREATE POLICY "Admins podem ver todos os perfis"
    ON public.profiles
    FOR SELECT
    USING (
      public.check_is_admin()
      OR auth.uid() = id
    );

-- Usuário pode atualizar o próprio perfil
CREATE POLICY "Usuários podem atualizar seus próprios perfis"
    ON public.profiles
    FOR UPDATE
    USING (auth.uid() = id)
    WITH CHECK (auth.uid() = id);

-- Usuário pode inserir o próprio perfil
CREATE POLICY "Permitir insert do próprio perfil"
    ON public.profiles
    FOR INSERT
    WITH CHECK (auth.uid() = id);
