-- >>>>>>>>>>>>>>>>>> BEGIN supabase\migrations\20240713000000_enable_realtime_orders.sql >>>>>>>>>>>>>>>>>>
-- Habilitar realtime para a tabela orders.
-- ALTER PUBLICATION ADD TABLE nao tem IF NOT EXISTS: se a tabela ja for membro da
-- publicacao (ordens foi ativada pelo dashboard do Supabase), o comando estoura 42710
-- e derruba a aplicacao inteira. So adiciona quando realmente falta.
DO $$
BEGIN
    IF to_regclass('public.orders') IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM pg_publication_rel pr
           JOIN pg_publication p ON p.oid = pr.prpubid
           WHERE p.pubname = 'supabase_realtime'
             AND pr.prrelid = 'public.orders'::regclass
       ) THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.orders;
        RAISE NOTICE '[VOLTRIS] orders adicionada a publicacao supabase_realtime';
    END IF;
END $$;
-- <<<<<<<<<<<<<<<<<< END supabase\migrations\20240713000000_enable_realtime_orders.sql <<<<<<<<<<<<<<<<<<

