        CREATE TYPE notification_sound AS ENUM ('ping', 'chime', 'tone');
    END IF;
END $$;

-- 2. Tabela notifications
CREATE TABLE IF NOT EXISTS public.notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    type notification_type NOT NULL,
    read BOOLEAN DEFAULT false,
    sound notification_sound DEFAULT 'ping',
    created_at TIMESTAMPTZ DEFAULT timezone('utc', now())
);

-- Índices
CREATE INDEX IF NOT EXISTS idx_notifications_user_id ON public.notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_type ON public.notifications(type);
CREATE INDEX IF NOT EXISTS idx_notifications_created_at ON public.notifications(created_at DESC);

-- RLS
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

-- Policies
DROP POLICY IF EXISTS "Users can view their own notifications" ON public.notifications;
CREATE POLICY "Users can view their own notifications"
    ON public.notifications FOR SELECT
    USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can insert their own notifications" ON public.notifications;
CREATE POLICY "Users can insert their own notifications"
    ON public.notifications FOR INSERT
    WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Admin can view all notifications" ON public.notifications;
-- Mesmo caso da policy de profiles: EXISTS sobre public.profiles dentro desta policy
-- reentrava no RLS de profiles e derrubava notifications?select=* com o mesmo erro de
-- recursão. check_is_admin() é SECURITY DEFINER e corta o ciclo.
CREATE POLICY "Admin can view all notifications"
    ON public.notifications FOR SELECT
    USING (
        public.check_is_admin()
        OR auth.uid() = user_id
    );

-- UPDATE (parity FASE 7/9 — tambem aplicado via adicoes.sql; idempotente):
-- sem estas duas policies o "Mark as read" (sino do usuario e aba Notifications
-- do painel admin) e negado por RLS silenciosamente.
DROP POLICY IF EXISTS "Users can update their own notifications" ON public.notifications;
CREATE POLICY "Users can update their own notifications"
    ON public.notifications FOR UPDATE
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Admin can update all notifications" ON public.notifications;
-- check_is_admin() e SECURITY DEFINER: evita recursao de RLS sobre profiles.
CREATE POLICY "Admin can update all notifications"
    ON public.notifications FOR UPDATE
    USING (public.check_is_admin())
    WITH CHECK (public.check_is_admin());

-- 3. Tabela user_settings
CREATE TABLE IF NOT EXISTS public.user_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    notifications_enabled BOOLEAN DEFAULT true,
    sound_enabled BOOLEAN DEFAULT true,
    notification_categories JSON DEFAULT '"[\"ticket\", \"order\", \"system\", \"profile\"]"',
    sound_theme TEXT DEFAULT 'default',
    volume NUMERIC(3,2) DEFAULT 1.0,
    sound_volume INTEGER DEFAULT 70,
    created_at TIMESTAMPTZ DEFAULT timezone('utc', now())
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_user_settings_user_id ON public.user_settings(user_id);

ALTER TABLE public.user_settings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view their own settings" ON public.user_settings;
CREATE POLICY "Users can view their own settings"
    ON public.user_settings FOR SELECT
    USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can update their own settings" ON public.user_settings;
CREATE POLICY "Users can update their own settings"
    ON public.user_settings FOR UPDATE
    USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can insert their own settings" ON public.user_settings;
CREATE POLICY "Users can insert their own settings"
    ON public.user_settings FOR INSERT
    WITH CHECK (auth.uid() = user_id);
