-- >>>>>>>>>>>>>>>>>> BEGIN supabase\migrations\20260102000000_fix_license_secret_key.sql >>>>>>>>>>>>>>>>>>
-- =====================================================
-- FIX: Atualizar chave secreta na função generate_license_key
-- A chave deve ser idêntica à usada no aplicativo C#
-- =====================================================

-- Recriar função com chave correta
-- generate_license_key e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'generate_license_key'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION generate_license_key(
    p_client_id TEXT,
    p_valid_until DATE,
    p_plan TEXT
) RETURNS TEXT AS $$
DECLARE
    v_content TEXT;
    v_signature TEXT;
    v_formatted_date TEXT;
BEGIN
    -- Formatar data
    v_formatted_date := TO_CHAR(p_valid_until, 'YYYYMMDD');
    
    -- Criar conteúdo da licença (mesmo formato do app C#)
    v_content := json_build_object(
        'id', p_client_id,
        'validUntil', p_valid_until::TEXT,
        'plan', p_plan
    )::TEXT;
    
    -- Gerar assinatura usando a MESMA chave secreta do aplicativo
    -- CRÍTICO: Esta chave DEVE ser idêntica à:
    -- - LicenseSecurityService.cs (app)
    -- - LicenseGenerator/Program.cs
    v_signature := SUBSTRING(
        ENCODE(
            DIGEST(
                v_content || 'VOLTRIS_SECRET_LICENSE_KEY_2025', 
                'sha256'
            ), 
            'hex'
        ), 
        1, 
        16
    );
    
    -- Formatar chave final
    RETURN 'VOLTRIS-LIC-' || p_client_id || '-' || v_formatted_date || '-' || UPPER(v_signature);
END;
$$ LANGUAGE plpgsql;

-- Comentário explicativo
COMMENT ON FUNCTION generate_license_key(TEXT, DATE, TEXT) IS 
'Gera chave de licença compatível com o aplicativo Voltris Optimizer. 
IMPORTANTE: A chave secreta VOLTRIS_SECRET_LICENSE_KEY_2025 deve ser idêntica 
à usada no código C# para garantir compatibilidade.';
-- <<<<<<<<<<<<<<<<<< END supabase\migrations\20260102000000_fix_license_secret_key.sql <<<<<<<<<<<<<<<<<<

-- >>>>>>>>>>>>>>>>>> BEGIN supabase\migrations\20260102000001_standardize_license_plans.sql >>>>>>>>>>>>>>>>>>
-- =====================================================
-- PADRONIZAÇÃO DE PLANOS - VOLTRIS OPTIMIZER
-- Define planos corretos conforme requisito do usuário
-- =====================================================

-- ENUM license_type: vocabulario canonico INTL dos planos compraveis.
-- Fonte: lib/license-catalog.ts (PlanType = standard | pro | enterprise), espelhado no
-- aplicativo por LicenseOrchestrationService.cs e LicenseSignatureVerifier.cs (STA/PRO/ENT).
--
-- Porque a guarda mora aqui: as duas definicoes de license_type que o arquivo original
-- trazia (secoes do Mercado Pago) estao DENTRO de blocos de comentario e nunca executam. Este e o
-- primeiro ponto VIVO do script em que o tipo e consumido (code license_type logo abaixo),
-- entao e aqui que o tipo precisa ser alinhado antes de qualquer INSERT.
--
-- A guarda antiga só perguntava se o tipo EXISTIA. No banco ele existe com labels legadas
-- (basic/professional/gamer/corporate), entao o CREATE era pulado e o seed morria com
-- 22P02. Agora o CONJUNTO de labels e validado.
DO $$
DECLARE
    v_querido     text[] := ARRAY['standard', 'pro', 'enterprise'];
    v_atual       text[];
    v_dependentes integer;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_type t
        JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'license_type' AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.license_type AS ENUM ('standard', 'pro', 'enterprise');
        RETURN;
    END IF;

    SELECT array_agg(e.enumlabel ORDER BY e.enumsortorder)
      INTO v_atual
      FROM pg_enum e
     WHERE e.enumtypid = 'public.license_type'::regtype;

    IF v_atual = v_querido THEN
        RETURN;
    END IF;

-- Labels divergentes: so recria se NADA depender do tipo. 'a' e a dependencia automatica
-- (o array type do proprio enum) e 'i' e a interna (as linhas dele em pg_enum); nenhuma
-- das duas impede o DROP TYPE.
    SELECT count(*)
      INTO v_dependentes
      FROM pg_depend
     WHERE refclassid = 'pg_type'::regclass
       AND refobjid   = 'public.license_type'::regtype
       AND deptype NOT IN ('a', 'i');

    IF v_dependentes > 0 THEN
        RAISE EXCEPTION
            'license_type tem labels divergentes (%, esperado %) e % objeto(s) dependentes. Alinhe com ALTER TYPE ... RENAME VALUE ou remova os dependentes antes de aplicar o script.',
            array_to_string(v_atual, ', '), array_to_string(v_querido, ', '), v_dependentes;
    END IF;

    DROP TYPE public.license_type;
    CREATE TYPE public.license_type AS ENUM ('standard', 'pro', 'enterprise');
END$$;

-- Criar tabela de configuração de planos (se não existir)
CREATE TABLE IF NOT EXISTS license_plans (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    code license_type NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT,
    price_monthly NUMERIC(10,2),
    price_display TEXT NOT NULL,
    max_devices INTEGER NOT NULL DEFAULT 1,
    duration_months INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT true,
    features JSONB,
    display_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Planos canonicos INTL: standard | pro | enterprise (fonte: lib/license-catalog.ts,
-- espelhado no app por LicenseOrchestrationService.cs / LicenseSignatureVerifier.cs).
-- O preco mensal aqui e a base USD do catalogo; o preco final de cada idioma e resolvido
-- no servidor por (plano, periodo, moeda), entao esta tabela nao e autoridade de preco.
--
-- Antes: TRUNCATE + INSERT de 4 planos legados do BR (trial/pro/premium/enterprise, em R$).
-- Isso quebrava de tres jeito: (1) as labels trial/premium nao existem no enum canonico;
-- (2) o TRUNCATE apagava a tabela a cada aplicacao; (3) pro tinha max_devices=1 enquanto o
-- catalogo diz 3. Agora: upsert dos 3 planos reais, que atualiza preco/limites ao re-aplicar.
INSERT INTO license_plans
    (code, name, description, price_monthly, price_display, max_devices, duration_months, features, display_order)
VALUES
    ('standard', 'VOLTRIS STANDARD', 'Single-device license for personal use', 6.90,
     'USD 6.90 / month', 1, 1,
     '["All optimizations", "1 device", "Monthly billing", "Email support"]'::jsonb, 1),
    ('pro', 'VOLTRIS PRO', 'Three-device license for power users', 12.90,
     'USD 12.90 / month', 3, 1,
     '["All optimizations", "3 devices", "Monthly billing", "Priority support", "Advanced Gamer Mode", "Network optimizations"]'::jsonb, 2),
    ('enterprise', 'VOLTRIS ENTERPRISE', 'Unlimited-device license for teams and companies', 39.90,
     'USD 39.90 / month', 9999, 1,
     '["All optimizations", "Unlimited devices", "Monthly billing", "24/7 support", "Integration API", "Admin panel", "Batch deployment"]'::jsonb, 3)
ON CONFLICT (code) DO UPDATE SET
    name            = EXCLUDED.name,
    description     = EXCLUDED.description,
    price_monthly   = EXCLUDED.price_monthly,
    price_display   = EXCLUDED.price_display,
    max_devices     = EXCLUDED.max_devices,
    duration_months = EXCLUDED.duration_months,
    features        = EXCLUDED.features,
    display_order   = EXCLUDED.display_order,
    updated_at      = NOW();

-- Criar função helper para obter configuração de plano
-- get_plan_config e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'get_plan_config'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION get_plan_config(p_plan_code license_type)
RETURNS TABLE (
    code license_type,
    name TEXT,
    description TEXT,
    price NUMERIC(10,2),
    price_display TEXT,
    max_devices INTEGER,
    duration_months INTEGER,
    features JSONB
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        lp.code,
        lp.name,
        lp.description,
        lp.price_monthly,
        lp.price_display,
        lp.max_devices,
        lp.duration_months,
        lp.features
    FROM license_plans lp
    WHERE lp.code = p_plan_code AND lp.is_active = true;
END;
$$ LANGUAGE plpgsql;

-- Criar função para calcular data de expiração baseada no plano
-- calculate_expiry_date e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'calculate_expiry_date'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION calculate_expiry_date(
    p_plan_code license_type,
    p_start_date TIMESTAMPTZ DEFAULT NOW()
) RETURNS TIMESTAMPTZ AS $$
DECLARE
    v_months INTEGER;
    v_days INTEGER;
BEGIN
    -- Trial: 7 dias
    IF p_plan_code = 'trial' THEN
        RETURN p_start_date + INTERVAL '7 days';
    END IF;
    
    -- Obter duração em meses do plano
    SELECT duration_months INTO v_months
    FROM license_plans
    WHERE code = p_plan_code AND is_active = true;
    
    -- Se não encontrou, usar 1 mês como padrão
    IF v_months IS NULL THEN
        v_months := 1;
    END IF;
    
    -- Adicionar meses à data de início
    RETURN p_start_date + (v_months || ' months')::INTERVAL;
END;
$$ LANGUAGE plpgsql;

-- Adicionar índice
CREATE INDEX IF NOT EXISTS idx_license_plans_code ON license_plans(code);
CREATE INDEX IF NOT EXISTS idx_license_plans_is_active ON license_plans(is_active);

-- Comentários
COMMENT ON TABLE license_plans IS 'Configuração centralizada dos planos de licença do Voltris Optimizer';
COMMENT ON FUNCTION get_plan_config(license_type) IS 'Retorna configuração completa de um plano';
COMMENT ON FUNCTION calculate_expiry_date(license_type, TIMESTAMPTZ) IS 'Calcula data de expiração baseada no plano e data de início';
-- <<<<<<<<<<<<<<<<<< END supabase\migrations\20260102000001_standardize_license_plans.sql <<<<<<<<<<<<<<<<<<

