CREATE INDEX IF NOT EXISTS idx_subscriptions_mp_subscription ON subscriptions(mp_subscription_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_status ON subscriptions(status);
CREATE INDEX IF NOT EXISTS idx_subscriptions_next_billing ON subscriptions(next_billing_date) WHERE status = 'active';
*/

-- [INTL][skip] subscription_payments: linhagem BR/Mercado Pago (mp_payment_id),
-- nao usada pelo codigo INTL. O CREATE desta tabela nao seria pulado (ela nao
-- existe no INTL) e o FK license_id REFERENCES licenses(id) daria 42703 contra a
-- licenses canonica (PK license_key, sem "id" — ver FASE 6). Encapsulado.
/*
-- 2. Criar tabela de histórico de pagamentos
