    license_id UUID NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,
    
    -- Mercado Pago
    mp_payment_id TEXT UNIQUE NOT NULL,
    mp_collection_id TEXT,
    mp_collection_status TEXT, -- approved, pending, rejected, etc
    
