  IF confirmation_token != 'DELETE_CONFIRMED' THEN
    RAISE EXCEPTION 'Invalid confirmation token';
  END IF;
  
  WITH 
    deleted_events AS (
      DELETE FROM telemetry_events 
      WHERE device_id IN (SELECT id FROM devices WHERE company_id = target_company_id)
      RETURNING 1
    ),
    deleted_devices AS (
      DELETE FROM devices 
      WHERE company_id = target_company_id
      RETURNING 1
    )
  SELECT jsonb_build_object(
    'events_deleted', (SELECT COUNT(*) FROM deleted_events),
    'devices_deleted', (SELECT COUNT(*) FROM deleted_devices)
  ) INTO deleted_count;
  
  RETURN deleted_count;
END;
$$;

-- ============================================================================
-- 5. get_plan_config - License Plans
-- ============================================================================
DROP FUNCTION IF EXISTS get_plan_config CASCADE;

-- get_plan_config e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'get_plan_config'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION get_plan_config(p_plan_code license_type)
RETURNS TABLE (
    code license_type,
    name TEXT,
    duration_days INTEGER,
    max_devices INTEGER,
    features JSONB
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p_plan_code,
    CASE p_plan_code
      WHEN 'trial' THEN 'Trial'
      WHEN 'standard' THEN 'Standard'
      WHEN 'pro' THEN 'Pro'
      WHEN 'enterprise' THEN 'Enterprise'
    END::TEXT,
    CASE p_plan_code
      WHEN 'trial' THEN 7
      WHEN 'standard' THEN 30
      WHEN 'pro' THEN 365
      WHEN 'enterprise' THEN 365
    END::INTEGER,
    CASE p_plan_code
      WHEN 'trial' THEN 1
      WHEN 'standard' THEN 3
      WHEN 'pro' THEN 10
      WHEN 'enterprise' THEN 999
    END::INTEGER,
    CASE p_plan_code
      WHEN 'trial' THEN '{"basic": true}'::JSONB
      WHEN 'standard' THEN '{"basic": true, "advanced": false}'::JSONB
      WHEN 'pro' THEN '{"basic": true, "advanced": true}'::JSONB
      WHEN 'enterprise' THEN '{"basic": true, "advanced": true, "enterprise": true}'::JSONB
    END::JSONB;
END;
$$;

-- ============================================================================
-- 6. calculate_expiry_date - License Plans
-- ============================================================================
DROP FUNCTION IF EXISTS calculate_expiry_date CASCADE;

-- calculate_expiry_date e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'calculate_expiry_date'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION calculate_expiry_date(
    p_plan_code license_type,
    p_start_date TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    duration_days INTEGER;
BEGIN
    SELECT 
        CASE p_plan_code
            WHEN 'trial' THEN 7
            WHEN 'standard' THEN 30
            WHEN 'pro' THEN 365
            WHEN 'enterprise' THEN 365
        END
    INTO duration_days;
    
    RETURN p_start_date + (duration_days || ' days')::INTERVAL;
END;
$$;

