-- 7. generate_license_key - License Generation
-- ============================================================================
DROP FUNCTION IF EXISTS generate_license_key CASCADE;

-- generate_license_key e redefinida aqui com tipo de retorno diferente do
-- definition anterior: CREATE OR REPLACE nao troca o tipo (42P13), entao
-- remove-se qualquer sobrecarga existente antes de criar esta.
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT p.oid::regprocedure AS sig
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'generate_license_key'
    LOOP
        BEGIN
            EXECUTE 'DROP FUNCTION ' || r.sig;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[VOLTRIS] nao foi possivel remover % (%): %', r.sig, SQLERRM, SQLSTATE;
        END;
    END LOOP;
END $$;
CREATE OR REPLACE FUNCTION generate_license_key(
    p_client_id TEXT,
    p_valid_until DATE,
    p_plan_code license_type
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_secret_key TEXT := 'VOLTRIS_SECRET_2024_PRODUCTION';
    v_payload TEXT;
    v_hash TEXT;
BEGIN
    v_payload := p_client_id || '|' || p_valid_until::TEXT || '|' || p_plan_code::TEXT;
    v_hash := encode(digest(v_payload || v_secret_key, 'sha256'), 'hex');
    RETURN 'VOLTRIS-' || UPPER(SUBSTRING(v_hash FROM 1 FOR 8)) || '-' || 
           UPPER(SUBSTRING(v_hash FROM 9 FOR 8)) || '-' || 
           UPPER(SUBSTRING(v_hash FROM 17 FOR 8));
END;
$$;

